ini_set('display_errors', 1);
error_reporting(E_ALL);

$json = '{"assets/css/style.css":"","track-complaint.php":"","edit-complaint.php":"","includes/footer.php":"","database/infinityfree_schema.sql":"","includes/header.php":"","assets/js/main.js":"","includes/alerts.php":"","delete-complaint.php":"","view-complaint.php":"","index.php":"","submit-complaint.php":"","config/database.php":"","export.php":"","manage-complaints.php":""}';
$bundle = json_decode($json, true);

$created = [];
$errors = [];

foreach ($bundle as $relPath => $base64) {
    $targetPath = __DIR__ . '/' . str_replace('/', DIRECTORY_SEPARATOR, $relPath);
    $dir = dirname($targetPath);
    if (!is_dir($dir)) {
        if (!@mkdir($dir, 0755, true)) {
            $errors[] = "Failed to create directory: {$dir}";
            continue;
        }
    }
    $content = base64_decode($base64);
    if (file_put_contents($targetPath, $content) === false) {
        $errors[] = "Failed to write file: {$relPath}";
    } else {
        $created[] = $relPath;
    }
}

// Automatically execute schema if DB credentials work
$dbStatus = "";
$dbOk = false;
try {
    $pdo = new PDO("mysql:host=sql210.infinityfree.com;port=3306;dbname=if0_43438189_ocms_db;charset=utf8mb4", "if0_43438189", "jenni200601", [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
    ]);
    
    $sqlFile = __DIR__ . '/database/infinityfree_schema.sql';
    if (file_exists($sqlFile)) {
        $sql = file_get_contents($sqlFile);
        $pdo->exec($sql);
        $dbStatus = "Database tables and sample records imported successfully!";
        $dbOk = true;
    }
} catch (Exception $e) {
    $dbStatus = "Database setup note: " . $e->getMessage();
}
